import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山地剥","description":"周易折中 - 山地剥","frontmatter":{"title":"山地剥","description":"周易折中 - 山地剥"},"headers":[],"relativePath":"zh/classics/zhezhong/029.md","filePath":"zh/classics/zhezhong/029.md"}'),h={name:"zh/classics/zhezhong/029.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山地剥" tabindex="-1">山地剥 <a class="header-anchor" href="#山地剥" aria-label="Permalink to “山地剥”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>剥卦序：贲者，饰也；致饰然后亨，则尽矣，故受之以剥。夫物至于文饰，亨之极也，极则必反，故贲终则剥也。卦五阴而一阳，阴始自下生，渐长至于盛极，群阴湏剥于阳，故为剥也。以二体言之，山附于地，山高起地上而反附者于地，颓剥之象也。</p><p>剥：不利有攸往</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>剥落也。五阴在下而方生一阳在上而将尽，阴盛长而阳消落，九月之卦也。阴盛阳衰，小人壮而君子病。又内坤外艮，有顺时而止之象。故占得之者，不可以有所往也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>剥者，群阴长盛，消剥于阳之时。众小人剥丧于君子，故君子不利有所往。唯当巽言晦迹，随时消息，以免小人之害也。</p><p>象曰：山附于地，剥；上以厚下安宅</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>艮重于坤，山附于地也。山高起于地而反附着于地，圯剥之象也。上谓人君与居人上者，观剥之象而厚固其下以安其居也。下者上之本，未有基本固而能剥者也，故上之剥必自下。下剥则上危矣，为人上者知理之如是，则安养人民以厚其本，乃所以安其居也。书曰：“民惟邦本，本固邦宁。”</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰 ：山高绝于地，今附地者，明被剥矣。君当厚锡于下，然后得安其居。</p></li><li><p>刘氏牧曰 ：山以地为基，厚其地则山保其高；君以民为本，厚其下则君安于上。</p></li><li><p>司马氏光曰 ：基薄则墙颓，下薄则上危。故君子厚其下者，所以自安其居也。</p></li><li><p>朱子语类云 ：惟其地厚，所以山安其居而不摇。人君厚下以得民，则其位亦安而不摇，犹所谓“本固邦宁”也。</p></li></ul><p>彖曰：剥，剥也。柔变刚也</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义，言柔进干阳，变刚为柔也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>陈氏友文曰：《夬彖》曰“刚决柔”，而《剥》曰“柔变刚”，何也？君子之去小人，声其罪与天下共弃之，名正言顺，故曰“决”；小人之欲去君子，辞不顺理不直，必萋斐浸润以侵蚀之，故曰“变”。一字之闲，君子小人之情状皦然矣。</li></ul><p>不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体卦徳释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>剥，剥也，谓剥落也。柔变刚也，柔长而刚变也。夏至一阴生而渐长，一阴长则一阳消，至于建戌则极而成剥，是阴柔变刚阳也。阴小人之道方长盛而剥消于阳，故君子不利有所往也。君子当剥之时，知不可有所往，顺时而止，乃能观剥之象也。卦有顺止之象，乃处剥之道，君子当观而体之。君子尚消息盈虚，天行也。君子存心消息盈虚之理而能顺之，乃合乎天行也。理有消衰有息长，有盈满有虚损，顺之则吉，逆之则凶。君子随时敦尚，所以事天也。</p><p>初六：剥床以足，蔑贞凶</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>剥自下起，灭正则凶，故其占如此。蔑，灭也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>阴之剥阳，自下而上。以床为象者，取身之所处也。自下而剥，渐至于身也。剥床以足，剥床之足也。剥始自下，故为剥足。阴自下进，渐消灭于贞正，凶之道也。蔑，无也，谓消亡于正道也。阴剥阳，柔变刚，是邪侵正，小人消君子，其凶可知。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：阴之消阳自下而进，初在下，故为剥床而先以床足灭于下之象。当此“不利有攸往”之时，唯宜顺时而止耳。贞凶，戒占者固执而不知变，则凶也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>俞氏之说是以“蔑”字属上句读，盖自象传㓕下㸔出，亦可备一说。</p><p>象曰：剥床以足，以灭下也</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>取床足为象者，以阴侵没阳于下也。灭，没也，侵灭正道自下而上也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>虞氏翻曰 ：床所以安人，在下故称足。先从下剥，渐及于上，故曰“以灭下也”。</li></ul><p>六二：剥床以辨，蔑贞凶</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>辨，床干也，进而上矣。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>辨，分隔上下者，床之干也。阴渐进而上，剥至于辨，愈灭于正也，凶益甚矣。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：既灭初之足于下，又灭二之辨于中，则进而上矣。得此占者，若犹固执而不知变，则其凶必也。</li></ul><p>象曰：剥床以辨，未有与也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>言未大盛。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>阴之侵剥于阳，得以益盛，至于剥辨者，以阳未有应与故也。小人侵剥君子，若君子有与，则可以胜小人，不能为害矣。唯其无与，所以被蔑而凶。当消剥之时而无徒与，岂能自存也？言未有与，剥之未盛，有与犹可胜也。示人之意深矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰 ：辨当在笫足之间，是床梐也。未有与者，言至三则应，故二未有与也。</p></li><li><p>吴氏澄曰 ：若六三之剥，之唯其有与也。</p></li><li><p>龚氏焕曰 ：六二阴柔中正，使上有阳刚之与，则必应之助之而不为剥矣。惟其无与，所以杂于群阴之中而为剥。若三则有与，故虽不如二之中正，而得无咎。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>崔氏、吴氏、龚氏之说皆得文意。六三不中正而辞优于二，故圣人以“未有与”失上下明之。</p><p>六三：剥之无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>众阴方剥阳，而已独应之，去其党而从正，无咎之道也。占者如是，则得无咎。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>众阴剥阳之时，而三独居刚，应刚与上下之阴异矣。志从于正，在剥之时为无咎者也。三之为可谓善矣，不言吉何也？曰：方群阴剥阳，众小人害君子，三虽从正，其𫝑孤弱，所应在无位之地，于斯时也难乎免矣，安得吉也？其义为无咎耳。言其无咎，所以劝也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>荀氏爽曰：众皆剥阳，三独应上，无剥害意，是以无咎。</p></li><li><p>王氏弼曰：与上为应，群阴剥阳，我独协焉。虽处于剥，可以无咎。</p></li><li><p>胡氏炳文曰：剥之三即复之四。复六四不许以吉，剥六三许以无咎，何也？曰：复君子之事，明道不计功，不以吉许之可也。剥小人之事，小人中独知有君子，不以无咎许之，无以开其补过之门也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>王氏、程子皆以“剥之无咎”连读，言此乃剥时之无咎者也。玩本义似以“剥之”为“剥去其党”。</p><p>象曰：剥之无咎，失上下也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>上下谓四阴。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三居剥而无咎者，其所处与上下诸阴不同，是与其同类相失，于处剥之道为无咎，如东汉之吕强是也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：三上下各有二阴，而三独应于阳，则失上下也。</p></li><li><p>丘氏富国曰 ：上谓四五，下谓初二，违去四阴而独从刚，故曰失上下也。</p></li></ul><p>六四：剥床以肤，凶</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>阴祸切身，故不复言蔑贞，而直言凶也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>始剥于床足，渐至于肤。肤，身之外也，将灭其身矣，其凶可知。阴长已盛，阳剥已甚，贞道以消，故更不言蔑贞，直言凶也。</p><p>象曰：剥床以肤，切近灾也</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>五为君位，剥已及四，在人则剥其肤矣。剥及其肤，身垂于亡矣，切近于灾祸也。</p><p>六五：贯鱼以宫人宠，无不利</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>鱼阴物，宫人阴之美而受制于阳者也。五为众阴之长，当率其类受制于阳，故有此象。而占者如是，则无不利也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>剥及君位，剥之极也，其凶可知。故更不言剥，而别设义以开小人迁善之门。五，群阴之主也，鱼阴物，故以为象。五能使群阴顺序如贯鱼然，反获宠爱于在上之阳，如宫人，则无所不利也。宫人，宫中之人，妻妾侍使也。以阴言且取获宠爱之义，以一阳在上，众阴有顺从之道，故发此义。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：阴阳之际近必相比，六五能上附于阳，反制群阴，不使进逼，方得处剥之善。下无剥之之忧，上得阳功之庇，故曰无不利。</p></li><li><p>熊氏良辅曰：卦本为阴剥阳而阳凶，爻则以剥阳而见凶。故五则以顺上为无不利，三则以应上为无咎，而上则有硕果得舆之象焉。</p></li><li><p>张氏振渊曰：遁阴长而犹微，可制也，则告阳以制阴之道曰畜臣妾。剥阴长已极，不可制矣，则教阴以从阳之道曰以宫人宠。</p></li></ul><p>象曰：以宫人宠，终无尤也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>群阴消剥于阳以至于极，六五若能长率群阴，骈首顺序，反获宠爱于阳，则终无过尤也。于剥之将终，复发此义，圣人劝迁善之意深切之至也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>五以阴居尊，取后妃之象，而为贯鱼。以宫人宠，则岂有妒害渎乱以剥其君之尤哉？</p><p>上九：硕果不食，君子得舆，小人剥庐</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>一阳在上，剥未尽而能复生。君子在上，则为众阴所载；小人居之，则剥极于上，自失所覆，而无复“硕果得舆”之象矣。取象既明，而君子、小人其占不同，圣人之情益可见矣。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>诸阳削剥已尽，独有上九一爻尚存，如硕大之果，不见食，将见复生之理。上九亦变，则纯阴矣。然阳无可尽之理，变于上则生于下，无间可容息也。圣人发明此理，以见阳与君子之道不可亡也。或曰：“剥尽则为纯坤，岂复有阳乎？”曰：“以卦配月，则坤当十月。以气消息言，则阳剥为坤，阳来为复，阳未尝尽也。剥尽于上，则复生于下矣。故十月谓之阳月，恐疑其无阳也。阴亦然，圣人不言耳。阴道盛极之时，其乱可知。乱极则自当思治，故众心愿载于君子，君子得舆也。《诗》‘匪风下泉’，所以居变风之终也。理既如此，在卦亦众阴宗阳，为共载之象。小人剥庐，若小人则当剥之极，剥其庐矣，无所容其身也。”更不论爻之阴阳，但言小人处剥极，则及其庐矣。庐取在上之象。或曰：“阴阳之消，必待尽而后复生于下，此在上便有复生之义，何也？”《夬》之上六何以言“终有凶”？曰：“上九居剥之极，止有一阳，阳无可尽之理，故明其有复生之义，见君子之道不可亡也。《夬》者，阳消阴，阴小人之道也，故但言其消亡耳，何用更言却有复生之理乎？”</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>程子曰 ：“息训为生者，盖息则生矣。中无间断，硕果不食，则便为复也。”</p></li><li><p>杨氏文焕曰 ：“贯鱼者，众阴在下之象也；硕果者，一阳在上之象也。”</p></li><li><p>胡氏炳文曰 ：“乾为木果，众阳皆变而上独存，有硕果不食象。果中有仁，天地生生之心存焉。硕果专以象言，得舆、剥庐兼占而言。床上之藉，下以安者也；庐下之藉，上以安者也。始而剥床，欲上失所安；今而剥庐，自失所安矣。自古小人欲害君子，亦岂小人之利哉？”</p></li><li><p>蔡氏清曰 ：“《易》固为君子谋，然其为君子谋者，亦所以为小人谋也。观小人剥庐之辞可见。盖道理自是如此，天地间岂可一日无善类哉？不然，人之类灭矣。可见圣人非姑为是抑彼以伸此也。”</p></li><li><p>乔氏中和曰 ：“硕果不食，核也，仁也，生生之根也。自古无不朽之株，有相传之果，此剥之所以复也。”</p></li></ul><p>象曰：君子得舆，民所载也；小人剥庐，终不可用也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>正道消剥既极，则人复思治，故阳刚君子为民所承载也。若小人处剥之极，则小人之穷耳，终不可用也。非谓九为小人，但言剥极之时，小人如是也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云 ：唯君子乃能覆盖小人，小人必赖君子以保其身。今小人欲剥君子，则君子亡而小人亦无所容其身，如自剥其庐也。且自古小人欲害君子，到害得尽后，国破家亡，其小人曾有存活得者否？故圣人于象曰“君子得舆，民所载也；小人剥庐，终不可用也”。</li></ul>',101)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
